// Asset pool MG card thumbnail: The motion-graphic asset generated by the agent only has code and no preview image.
// (The resource library template card comes with a preview image, and there is no customized MG in the pool). Here is the code scene
// prepareTemplate renders a mini Remotion Player after the lazy compiler gate.
// Only words are in the middle frame), hover to play, move back to the middle frame. If compilation fails, it will fall back to the star placeholder (consistent with the old look and feel).
import { useEffect, useRef, useState } from 'react';
import { Player, type PlayerRef } from '@remotion/player';
import { prepareTemplate, type MgComponent } from '../template-host';
import type { MediaAsset } from '../editor/types';
import { Icon } from '../components/icons';
import { motionGraphicPreviewFrame } from './mgPreview';

interface MgThumbProps {
  asset: MediaAsset;
  fps: number;
  active: boolean;
  posterSrc?: string;
}

export function MgThumb({ asset, fps, active, posterSrc }: MgThumbProps) {
  const playerRef = useRef<PlayerRef | null>(null);
  const [compiled, setCompiled] = useState<MgComponent | null>(null);
  useEffect(() => {
    let alive = true;
    setCompiled(null);
    if (active && asset.code) {
      void prepareTemplate(asset.code).then(
        (component) => { if (alive) setCompiled(() => component); },
        () => undefined,
      );
    }
    return () => { alive = false; };
  }, [active, asset.code]);

  useEffect(() => {
    const player = playerRef.current;
    return () => player?.pause();
  }, [active]);

  if (!active) {
    return posterSrc
      ? <img src={posterSrc} alt={asset.name} draggable={false} />
      : <Icon name="sparkles" size={30} strokeWidth={0.9} />;
  }
  if (!compiled) return <Icon name="sparkles" size={30} strokeWidth={0.9} />;

  const width = asset.width ?? 1920;
  const height = asset.height ?? 1080;
  const duration = Math.max(1, asset.durationInFrames || 60);
  const Template = compiled;
  return (
    <Player
      ref={playerRef}
      component={Template}
      inputProps={{ item: { props: asset.props ?? {}, width, height } }}
      durationInFrames={duration}
      compositionWidth={width}
      compositionHeight={height}
      fps={fps}
      initialFrame={motionGraphicPreviewFrame(duration)}
      loop
      autoPlay
      initiallyMuted
      numberOfSharedAudioTags={0}
      controls={false}
      clickToPlay={false}
      style={{ width: '100%', height: '100%', pointerEvents: 'none' }}
      acknowledgeRemotionLicense
    />
  );
}
